package by.lab.host;
import by.lab.contract.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.grpc.*;
import io.grpc.stub.StreamObserver;
import jakarta.annotation.*;
import java.util.*;
import org.springframework.context.ApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class RpcServer {
 private final ApplicationContext context; private final JdbcTemplate db; private final ObjectMapper json=new ObjectMapper(); private Server server;
 private static final Context.Key<Metadata> HEADERS=Context.key("rpc-headers");
 private final String name;
 public RpcServer(ApplicationContext context,JdbcTemplate db,@org.springframework.beans.factory.annotation.Value("${service.name}") String name){this.context=context;this.db=db;this.name=name;}
 @PostConstruct public void start() throws Exception { server=ServerBuilder.forPort(9090).addService(ServerInterceptors.intercept(new Data(),metadataInterceptor())).addService(new Methods()).addService(ServerInterceptors.intercept(new Accounts(),metadataInterceptor())).addService(new Payments()).build().start(); }
 private ServerInterceptor metadataInterceptor() { return new ServerInterceptor() { public <ReqT,RespT> ServerCall.Listener<ReqT> interceptCall(ServerCall<ReqT,RespT> call,Metadata headers,ServerCallHandler<ReqT,RespT> next) { return Contexts.interceptCall(Context.current().withValue(HEADERS,headers),call,headers,next); } }; }
 @PreDestroy public void stop(){if(server!=null) server.shutdown();}
 private Object service() throws Exception {String title=Character.toUpperCase(name.charAt(0))+name.substring(1);return context.getBean(Class.forName("by.lab."+name+"."+title+"Service"));}
 private void fail(StreamObserver<?> out,Exception e){ Throwable t=e instanceof java.lang.reflect.InvocationTargetException ? e.getCause():e; Status s=t instanceof StatusRuntimeException ? ((StatusRuntimeException)t).getStatus() : t instanceof SecurityException ? Status.PERMISSION_DENIED : t instanceof IllegalArgumentException?Status.INVALID_ARGUMENT:Status.INTERNAL; out.onError(s.withDescription(t.getMessage()).asRuntimeException()); }
 private class Data extends DataServiceGrpc.DataServiceImplBase {
  @SuppressWarnings("unchecked") public void call(DataRequest r,StreamObserver<DataResponse> out){try {Object s=service(),result; Object input=r.getPayloadJson().isEmpty()?null:json.readValue(r.getPayloadJson(),Object.class); switch(r.getOperation()) {
   case "list": result=s.getClass().getMethod("list").invoke(s);break;
   case "find": result=s.getClass().getMethod("find",String.class).invoke(s,r.getId());break;
   case "search": {var m=(Map<String,Object>)input;result=s.getClass().getMethod("search",Map.class,Map.class).invoke(s,m.get("filter"),m.get("sort"));break;}
   case "summary": result=s.getClass().getMethod("summary",Map.class).invoke(s,input);break;
   case "create": authorizeCreate((Map<String,Object>)input); result=context.getBean("paymentOperations").getClass().getMethod("create",Map.class).invoke(context.getBean("paymentOperations"),input);break;
   case "transition": authorizeTransition(r.getId(),(String)input); result=context.getBean("paymentOperations").getClass().getMethod("transition",String.class,String.class).invoke(context.getBean("paymentOperations"),r.getId(),input);break;
   case "createRefund": authorizeRefund((Map<String,Object>)input); result=context.getBean("refundOperations").getClass().getMethod("create",Map.class).invoke(context.getBean("refundOperations"),input); break;
   case "addMethod": { var a=actor(); var m=(Map<String,Object>)input; String owner=Objects.toString(m.get("clientId"),""); if(!name.equals("paymentmethod")) throw new IllegalArgumentException("Wrong service"); if(!admin(a) && !("CLIENT".equals(a.get("role")) && Objects.equals(a.get("id"),owner))) throw new SecurityException("Access denied"); var user=remoteFind("identity",owner); if(user==null || !"CLIENT".equals(user.get("role"))) throw new IllegalArgumentException("Client does not exist"); result=s.getClass().getMethod("add",String.class,String.class,String.class).invoke(s,owner,m.get("type"),m.get("lastFour")); break; }
   case "removeMethod": { var a=actor(); if(!name.equals("paymentmethod")) throw new IllegalArgumentException("Wrong service"); var method=(Map<String,Object>)s.getClass().getMethod("find",String.class).invoke(s,r.getId()); if(method==null) throw new IllegalArgumentException("Payment method not found"); if(!admin(a) && !("CLIENT".equals(a.get("role")) && Objects.equals(a.get("id"),method.get("client_id")))) throw new SecurityException("Access denied"); result=s.getClass().getMethod("remove",String.class).invoke(s,r.getId()); break; }
   case "byEmail": if(!name.equals("identity")) throw new IllegalArgumentException("Wrong service"); result=s.getClass().getMethod("findByEmail",String.class).invoke(s,r.getId()); break;
   case "registerUser": authorizeInternal(); if(!name.equals("identity")) throw new IllegalArgumentException("Wrong service"); var u=(Map<String,Object>)input; result=s.getClass().getMethod("register",String.class,String.class,String.class).invoke(s,u.get("id"),u.get("name"),u.get("email")); break;
   default: throw new IllegalArgumentException("Unknown operation"); }
   out.onNext(DataResponse.newBuilder().setPayloadJson(json.writeValueAsString(result)).build());out.onCompleted();}catch(Exception e){fail(out,e);}}
 }
 private String header(String key) { Metadata h=HEADERS.get(); return h==null?null:h.get(Metadata.Key.of(key,Metadata.ASCII_STRING_MARSHALLER)); }
 private void authorizeInternal() { String expected=System.getenv("INTERNAL_SERVICE_SECRET"),provided=header("x-internal-secret"); if(expected==null || expected.isBlank() || provided==null || !java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),provided.getBytes(java.nio.charset.StandardCharsets.UTF_8))) throw Status.UNAUTHENTICATED.withDescription("Internal authentication required").asRuntimeException(); }
 @SuppressWarnings("unchecked") private Map<String,Object> actor() {
  String token=header("authorization"); if(token==null || !token.startsWith("Bearer ")) throw Status.UNAUTHENTICATED.withDescription("Authentication required").asRuntimeException();
  try { String base=System.getenv().getOrDefault("AUTH_URL","http://auth-service:8081"); return org.springframework.web.client.RestClient.create(base).get().uri("/verify").header("Authorization",token).retrieve().body(Map.class); }
  catch(org.springframework.web.client.HttpClientErrorException e) { throw Status.UNAUTHENTICATED.withDescription("Invalid session").asRuntimeException(); }
  catch(org.springframework.web.client.RestClientException e) { throw Status.UNAVAILABLE.withDescription("Auth unavailable").asRuntimeException(); }
 }
 private boolean admin(Map<String,Object> actor) { return "ADMIN".equals(actor.get("role")); }
 private void authorizeCreate(Map<String,Object> input) { if(!name.equals("payment")) throw new IllegalArgumentException("Wrong service"); Map<String,Object> a=actor(); if(!admin(a) && !("CLIENT".equals(a.get("role")) && Objects.equals(a.get("id"),input.get("clientId")))) throw new SecurityException("Access denied"); }
 @SuppressWarnings("unchecked") private Map<String,Object> remoteFind(String service,String id) { ManagedChannel c=ManagedChannelBuilder.forAddress(System.getenv().getOrDefault(service.toUpperCase()+"_HOST",service+"-service"),9090).usePlaintext().build(); try { String value=DataServiceGrpc.newBlockingStub(c).withDeadlineAfter(4,java.util.concurrent.TimeUnit.SECONDS).call(DataRequest.newBuilder().setOperation("find").setId(id).build()).getPayloadJson(); return json.readValue(value,Map.class); } catch(Exception e) { throw new IllegalStateException("Cannot retrieve "+service,e); } finally { c.shutdown(); } }
 private boolean ownsMerchant(Map<String,Object> actor,String merchantId) { var merchant=remoteFind("merchant",merchantId); return merchant!=null && Objects.equals(actor.get("id"),merchant.get("user_id")); }
 @SuppressWarnings("unchecked") private void authorizeTransition(String id,String status) throws Exception { if(!name.equals("payment")) throw new IllegalArgumentException("Wrong service"); var a=actor(); var payment=(Map<String,Object>)service().getClass().getMethod("find",String.class).invoke(service(),id); if(payment==null) throw new IllegalArgumentException("Payment not found"); if(!admin(a) && !("CANCELLED".equals(status) && "CLIENT".equals(a.get("role")) && Objects.equals(a.get("id"),payment.get("client_id"))) && !("SUCCESS".equals(status) && "MERCHANT".equals(a.get("role")) && ownsMerchant(a,payment.get("merchant_id").toString()))) throw new SecurityException("Access denied"); }
 private void authorizeRefund(Map<String,Object> input) { if(!name.equals("refund")) throw new IllegalArgumentException("Wrong service"); var a=actor(); var payment=remoteFind("payment",Objects.toString(input.get("paymentId"),"")); if(payment==null) throw new IllegalArgumentException("Payment not found"); if(!admin(a) && !("CLIENT".equals(a.get("role")) && Objects.equals(a.get("id"),payment.get("client_id"))) && !("MERCHANT".equals(a.get("role")) && ownsMerchant(a,payment.get("merchant_id").toString()))) throw new SecurityException("Access denied"); }
 private class Methods extends PaymentMethodServiceGrpc.PaymentMethodServiceImplBase { public void validatePaymentMethod(ValidatePaymentMethodRequest r,StreamObserver<ValidatePaymentMethodResponse> out){try{if(!name.equals("paymentmethod")) throw new IllegalStateException("Wrong service"); var rows=db.queryForList("select client_id,status from paymentmethod.payment_methods where id=?",r.getPaymentMethodId());var row=rows.isEmpty()?Map.of():rows.get(0);String status=Objects.toString(row.get("status"),"NOT_FOUND");out.onNext(ValidatePaymentMethodResponse.newBuilder().setStatus(status).setValid(r.getClientId().equals(row.get("client_id")) && status.equals("ACTIVE")).build());out.onCompleted();}catch(Exception e){fail(out,e);}} }
 private class Accounts extends AccountServiceGrpc.AccountServiceImplBase {
  public void debitAccount(DebitAccountRequest r,StreamObserver<DebitAccountResponse> out) { try {
   if(!name.equals("account")) throw new IllegalArgumentException("Wrong service"); String path=System.getenv("ACCOUNT_SERVICE_SECRET_FILE"),provided=header("x-payment-service-secret");
   if(path==null || provided==null) throw Status.UNAUTHENTICATED.withDescription("Service authentication required").asRuntimeException();
   String expected=java.nio.file.Files.readString(java.nio.file.Path.of(path)).trim(); if(expected.isBlank() || !java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),provided.getBytes(java.nio.charset.StandardCharsets.UTF_8))) throw Status.UNAUTHENTICATED.withDescription("Service authentication required").asRuntimeException();
   ManagedChannel channel=ManagedChannelBuilder.forAddress(System.getenv().getOrDefault("PAYMENT_HOST","payment-service"),9090).usePlaintext().build(); GetPaymentResponse payment;
   try { payment=PaymentServiceGrpc.newBlockingStub(channel).withDeadlineAfter(4,java.util.concurrent.TimeUnit.SECONDS).getPayment(GetPaymentRequest.newBuilder().setPaymentId(r.getPaymentId()).build()); } finally { channel.shutdown(); }
   if(!"CREATED".equals(payment.getStatus()) || !payment.getClientId().equals(r.getOwnerId()) || !payment.getCurrency().equals(r.getCurrency()) || new java.math.BigDecimal(payment.getAmountDecimal()).compareTo(new java.math.BigDecimal(r.getAmount()))!=0) throw new IllegalArgumentException("Debit does not match payment");
   var op=context.getBean("accountOperations"); op.getClass().getMethod("debit",String.class,String.class,String.class,java.math.BigDecimal.class).invoke(op,r.getPaymentId(),r.getOwnerId(),r.getCurrency(),new java.math.BigDecimal(r.getAmount()));
   out.onNext(DebitAccountResponse.newBuilder().setApplied(true).build()); out.onCompleted();
  } catch(Exception e) { fail(out,e); } }
  public void checkAccount(CheckAccountRequest r,StreamObserver<CheckAccountResponse> out){try{if(!name.equals("account")) throw new IllegalStateException("Wrong service");var rows=db.queryForList("select status,balance,currency from account.accounts where id=? or owner_id=?",r.getAccountId(),r.getAccountId());var row=rows.stream().filter(x->r.getCurrency().equals(x.get("currency"))).findFirst().orElse(Map.of());String status=Objects.toString(row.get("status"),"NOT_FOUND");boolean ok=status.equals("ACTIVE") && new java.math.BigDecimal(row.get("balance").toString()).compareTo(java.math.BigDecimal.valueOf(r.getAmount()))>=0;out.onNext(CheckAccountResponse.newBuilder().setAllowed(ok).setStatus(status).build());out.onCompleted();}catch(Exception e){fail(out,e);}} }
 private class Payments extends PaymentServiceGrpc.PaymentServiceImplBase { public void getPayment(GetPaymentRequest r,StreamObserver<GetPaymentResponse> out){try{if(!name.equals("payment")) throw new IllegalStateException("Wrong service");var row=(Map<String,Object>)service().getClass().getMethod("find",String.class).invoke(service(),r.getPaymentId());if(row==null){out.onError(Status.NOT_FOUND.asRuntimeException());return;}out.onNext(GetPaymentResponse.newBuilder().setPaymentId(r.getPaymentId()).setClientId(row.get("client_id").toString()).setMerchantId(row.get("merchant_id").toString()).setAmount(Double.parseDouble(row.get("amount").toString())).setAmountDecimal(row.get("amount").toString()).setCurrency(row.get("currency").toString()).setStatus(row.get("status").toString()).build());out.onCompleted();}catch(Exception e){fail(out,e);}} }
}
